INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-registry-search','Search French companies by name or SIREN (top 10)','French company search and company lookup by name or SIREN in the official French company registry (INSEE Sirene / INPI RNE open data). Name search returns the top 10 matches with identity, SIREN, NAF code, city and active/ceased status, plus a score_confiance (0-1 match confidence) that helps disambiguate homonyms. The entry point to official data and company data on France: resolve a trading name to its SIREN identifier before pulling the full company profile, filings or financials. Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type":"object","properties":{"q":{"type":"string","description":"Company name, or a French identifier (SIREN, SIRET, VAT) — spaced or labelled (\"SIREN : 552 032 534\") resolves directly. Unsupported characters are stripped, not rejected; 400 only if nothing searchable is left (1-100 chars once cleaned).","x-parameter-location":"query"}},"required":["q"]}'::jsonb,'{"type":"object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.registry-profile','Full company profile by SIREN','Full French company profile by SIREN: official company data from the French company registry (INSEE Sirene / INPI RNE). One company lookup returns legal name, legal form, head-office address, NAF code, workforce bracket, creation date, active or ceased status, officers with name and role, collective agreement and the computed intra-EU VAT number. The core KYB building block for verifying a French counterparty: registry facts for due diligence, compliance and onboarding checks. Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type":"object","properties":{"siren":{"type":"string","pattern":"^\\d{9}$","description":"9-digit SIREN (Luhn-validated)","x-parameter-location":"path"},"geo":{"type":"boolean","description":"true = include GPS coordinates (WGS84) of establishments","x-parameter-location":"query"}},"required":["siren"]}'::jsonb,'{"type":"object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-financials','Annual financial data from filed accounts (INPI / Banque de France ratios)','Annual financial data from filed accounts (INPI / Banque de France ratios) Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type":"object","properties":{"siren":{"type":"string","pattern":"^\\d{9}$","description":"siren","x-parameter-location":"path"}},"required":["siren"]}'::jsonb,'{"type":"object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('company.fr-kyb','Complete KYB file for a French company (one call)','Complete KYB file for a French company (one call) Preserve provenance states, partial coverage, financial quality flags and nulls; null never means zero.','company','{"type":"object","properties":{"siren":{"type":"string","pattern":"^\\d{9}$","description":"9-digit SIREN (Luhn-validated)","x-parameter-location":"path"}},"required":["siren"]}'::jsonb,'{"type":"object"}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

